import fs from'node:fs';import crypto from'node:crypto';import{createRequire}from'node:module';import{specs}from'./clock-v17.mjs';const sharp=createRequire(import.meta.url)(process.env.CODEX_PRIMARY_RUNTIME_NODE_MODULES+'/sharp');let rows=[];
